extractDbName.source_lines:
function extractDbName(uri: string): string {
  try {
    const url = new URL(uri);
    const path = url.pathname;
    // pathname is "/<dbname>" or "/<dbname>?options"
    const name = path.replace(/^\//, "").split("?")[0];
    return name || "pando";
  } catch {
    return "pando";
  }
}

