export function clearRestartReason(dataDir?: string): void {
  const filePath = getReasonPath(dataDir);
  if (existsSync(filePath)) {
    try {
      unlinkSync(filePath);
      console.log('[restart-reason] Cleared restart reason file.');
    } catch {}
  }
}

