function launch() {
  const child = fork(entrypoint, nodeArgs, {
    cwd: root,
    stdio: 'inherit',
  });

  child.on('exit', (code) => {
    if (code === RESTART_EXIT_CODE) {
      console.log('\n[launcher] Restart requested (auto-update). Relaunching...\n');
      // Small delay to let ports release
      setTimeout(launch, 2000);
    } else {
      process.exit(code ?? 0);
    }
  });

