  if (d <= 0) return "Ended";
  if (d < 3600000) return `${Math.floor(d / 60000)}m left`;
  if (d < 86400000) return `${Math.floor(d / 3600000)}h left`;
  return `${Math.floor(d / 86400000)}d left`;
}

