NodePool.recordFailure.source_lines:
recordFailure(url: string): void {
  const entry = this.nodes.get(url);
  if (!entry) return;
  entry.consecutiveFailures++;
  if (entry.consecutiveFailures >= MAX_FAILURES_BEFORE_CIRCUIT) {
    entry.circuitOpen = true;
