export function parsePort(portArg?: string): number {
  if (!portArg) return 0;
  const port = parseInt(portArg, 10);
  if (isNaN(port) || port < 0 || port > 65535) {
    throw new Error(`Invalid port: ${portArg}`);
  }
  return port;
}

