    if (!this.preferredPeerId || !peers.includes(this.preferredPeerId)) {
      return peers;
    }
    // Move preferred to front
    return [
      this.preferredPeerId,
      ...peers.filter(p => p !== this.preferredPeerId),
    ];
  }
